<?php
// CLI-only, journalled, name-based homepage deployment. Never put this file in public_html.
if(PHP_SAPI!=='cli'||PHP_VERSION_ID<70300){fwrite(STDERR,"CLI PHP 7.3+ required\n");exit(2);}
umask(0007);
$release=realpath(__DIR__);$plan=json_decode(file_get_contents($release.'/plan.json'),true);
if(!$plan||$plan['remoteStage']!==$release||strpos($release,'/home/i/idealstroy/_codex_releases/homepage-')!==0||$plan['remoteRoot']!=='/home/i/idealstroy/isipto.ru/public_html')exit(2);
$root=realpath($plan['remoteRoot']);if(!$root||posix_geteuid()===0)exit(2);
$spec=json_decode(file_get_contents($release.'/release-spec.json'),true);$manifest=json_decode(file_get_contents($release.'/manifest.json'),true);$baseline=json_decode(file_get_contents($release.'/approved-baseline.json'),true);
if(!$spec||!$manifest||count($manifest)!==7||count($spec['files'])!==7||!$baseline)exit(2);
$action=isset($argv[1])?$argv[1]:'';if(!in_array($action,array('inspect','prepare','activate','status','rollback','lead-status'),true))exit(2);
$stateFile=$release.'/state.json';$state=is_file($stateFile)?json_decode(file_get_contents($stateFile),true):null;$modx=null;
require $root.'/core/config/config.inc.php';
$pdo=new PDO('mysql:host='.$database_server.';dbname='.$dbase.';charset=utf8',$database_user,$database_password,array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_STRINGIFY_FETCHES=>true));
function rowById($table,$id){global $pdo,$table_prefix;return $pdo->query('SELECT * FROM `'.$table_prefix.$table.'` WHERE id='.(int)$id)->fetch(PDO::FETCH_ASSOC);}
function homeRow(){global $pdo,$table_prefix;$id=$pdo->query('SELECT value FROM `'.$table_prefix.'context_setting` WHERE context_key=\'web\' AND `key`=\'site_start\'')->fetchColumn();if(!$id)$id=$pdo->query('SELECT value FROM `'.$table_prefix.'system_settings` WHERE `key`=\'site_start\'')->fetchColumn();$row=rowById('site_content',$id);if(!$row||$row['context_key']!=='web')throw new Exception('Cannot identify web homepage');return $row;}
function journal(){global $state,$stateFile;$temp=$stateFile.'.tmp';if(file_put_contents($temp,json_encode($state,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX)===false)throw new Exception('Cannot write deployment journal');chmod($temp,0600);if(!rename($temp,$stateFile))throw new Exception('Cannot commit deployment journal');}
function bootstrapModx(){global $modx,$root;if($modx)return;$_SERVER['HTTP_HOST']='isipto.ru';$_SERVER['SERVER_NAME']='isipto.ru';$_SERVER['HTTPS']='on';$_SERVER['REQUEST_URI']='/';define('MODX_API_MODE',true);require $root.'/config.core.php';require MODX_CORE_PATH.'model/modx/modx.class.php';$modx=new modX();$modx->initialize('web');}
function preserveCacheAcl(){global $root;$cache=realpath($root.'/core/cache');if(!$cache||$cache!==$root.'/core/cache')throw new Exception('Unexpected cache path');$uid=posix_geteuid();$iterator=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($cache,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST,RecursiveIteratorIterator::CATCH_GET_CHILD);foreach($iterator as $entry){if($entry->isLink()||$entry->getOwner()!==$uid)continue;if(!chmod($entry->getPathname(),$entry->isDir()?0770:0660))throw new Exception('Cannot preserve inherited site ACL on new cache item');}}
function refreshHomepageCache(){global $modx;$result=$modx->cacheManager->refresh(array('resource'=>array('contexts'=>array('web')),'db'=>array(),'scripts'=>array()));preserveCacheAcl();if($result===false)throw new Exception('Native cache refresh failed');}
function assertBaseline(){global $baseline,$root,$manifest,$release,$spec,$plan,$pdo,$table_prefix;
 foreach($baseline['files'] as $file=>$digest)if(!is_file($root.'/'.$file)||hash_file('sha256',$root.'/'.$file)!==$digest)throw new Exception('Shared file changed since audit: '.$file);
 foreach($baseline['objects'] as $object){if(!in_array($object['table'],array('site_htmlsnippets','site_snippets','site_tmplvars','site_templates'),true))throw new Exception('Invalid baseline table');$row=rowById($object['table'],$object['id']);if(!$row||hash('sha256',json_encode($row))!==$object['sha256'])throw new Exception('MODX dependency changed since audit: '.$object['name']);}
 foreach($manifest as $entry){$file=$entry['path'];if(!in_array($file,$spec['files'],true)||strpos($file,'..')!==false||strpos($file,'\\')!==false||substr($file,0,1)==='/')throw new Exception('Invalid payload path');if(!is_file($release.'/payload/'.$file)||hash_file('sha256',$release.'/payload/'.$file)!==$entry['sha256'])throw new Exception('Payload hash mismatch: '.$file);if(realpath(dirname($root.'/'.$file))!==$root.'/'.dirname($file))throw new Exception('Unexpected target parent: '.$file);}
}
function assertHomeUnchanged(){global $state;$home=homeRow();if(hash('sha256',json_encode($home))!==$state['originalHomeSHA256'])throw new Exception('Homepage changed concurrently; refusing activation');}
function restoreOriginalHome(){global $state,$modx;bootstrapModx();$home=$modx->getObject('modResource',(int)$state['originalHome']['id']);$current=(int)$home->get('template');$original=(int)$state['originalHome']['template'];if($current!==$original&&(!isset($state['created']['template'])||$current!==(int)$state['created']['template']))throw new Exception('Homepage assigned to an unrelated template; manual review required');$home->set('template',$original);$home->set('editedon',time());if(!$home->save())throw new Exception('Rollback save failed');refreshHomepageCache();$state['phase']='rolled-back';$state['rolledBackAt']=gmdate('c');journal();}
try{
 if($action==='inspect'){
  assertBaseline();$home=homeRow();$template=rowById('site_templates',$home['template']);if(!$template||$template['static_file']!==$plan['expectedOriginalTemplateFile'])throw new Exception('Homepage is no longer on approved original template');
  $targets=array();foreach($manifest as $entry){$file=$root.'/'.$entry['path'];if(file_exists($file)||is_link($file))throw new Exception('Target already exists; do not overwrite: '.$entry['path']);if(!is_writable(dirname($file)))throw new Exception('Target directory not writable');$targets[]=$entry['path'];}
  foreach(array(array('site_templates','templatename',$spec['template']['name']),array('site_htmlsnippets','name',$spec['chunk']['name'])) as $definition){$query=$pdo->prepare('SELECT id FROM `'.$table_prefix.$definition[0].'` WHERE `'.$definition[1].'`=?');$query->execute(array($definition[2]));if($query->fetchColumn())throw new Exception('Target element already exists; review before deployment');}
  echo json_encode(array('status'=>'READY_TO_PREPARE','php'=>PHP_VERSION,'home'=>(int)$home['id'],'originalTemplate'=>(int)$home['template'],'payloadFiles'=>$targets,'publicChanges'=>false))."\n";exit;
 }
 if($action==='status'){$home=homeRow();echo json_encode(array('phase'=>$state?$state['phase']:'not-prepared','home'=>(int)$home['id'],'template'=>(int)$home['template'],'created'=>$state?$state['created']:array(),'php'=>PHP_VERSION))."\n";exit;}
 if($action==='lead-status'){
  if(!$state)throw new Exception('No deployment state');$columns=$pdo->query('SHOW COLUMNS FROM `'.$table_prefix.'formit_forms`')->fetchAll(PDO::FETCH_COLUMN);$select=array_values(array_intersect(array('id','form','context_key','date'),$columns));$names=array_map(function($v){return '`'.$v.'`';},$select);$rows=$pdo->query('SELECT '.implode(',',$names).' FROM `'.$table_prefix.'formit_forms` WHERE id>'.(int)$state['formitBeforeMaxId'].' ORDER BY id LIMIT 30')->fetchAll(PDO::FETCH_ASSOC);echo json_encode(array('baselineId'=>$state['formitBeforeMaxId'],'newRecordMetadata'=>$rows,'crmReceiptConfirmed'=>false),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n";exit;
 }
 if($action==='rollback'){if(!$state)throw new Exception('No rollback journal');restoreOriginalHome();echo json_encode(array('phase'=>$state['phase'],'restoredTemplate'=>(int)$state['originalHome']['template'],'fullDatabaseRestored'=>false))."\n";exit;}
 if($action==='prepare'){
  if($state)throw new Exception('Deployment already has a journal; inspect before retry');assertBaseline();$home=homeRow();$originalTemplate=rowById('site_templates',$home['template']);if(!$originalTemplate||$originalTemplate['static_file']!==$plan['expectedOriginalTemplateFile'])throw new Exception('Unexpected original template');
  foreach($manifest as $entry)if(file_exists($root.'/'.$entry['path'])||is_link($root.'/'.$entry['path']))throw new Exception('Existing target; refusing overwrite');
  $bindings=$pdo->query('SELECT * FROM `'.$table_prefix.'site_tmplvar_templates` WHERE templateid='.(int)$home['template'].' ORDER BY tmplvarid')->fetchAll(PDO::FETCH_ASSOC);
  $state=array('release'=>$plan['id'],'phase'=>'preparing','preparedAt'=>gmdate('c'),'originalHome'=>$home,'originalHomeSHA256'=>hash('sha256',json_encode($home)),'originalTemplate'=>$originalTemplate,'originalBindings'=>$bindings,'created'=>array(),'installedFiles'=>array(),'formitBeforeMaxId'=>(int)$pdo->query('SELECT MAX(id) FROM `'.$table_prefix.'formit_forms`')->fetchColumn());journal();
  foreach($manifest as $entry){$target=$root.'/'.$entry['path'];$temp=$target.'.'.$plan['id'].'.partial';$in=fopen($release.'/payload/'.$entry['path'],'rb');$out=fopen($temp,'xb');if(!$in||!$out)throw new Exception('Cannot open payload copy streams');if(stream_copy_to_stream($in,$out)!==$entry['bytes'])throw new Exception('Short payload copy');fclose($in);fflush($out);fclose($out);if(hash_file('sha256',$temp)!==$entry['sha256'])throw new Exception('Copied payload hash mismatch');if(!chmod($temp,0660))throw new Exception('Cannot retain writable site ACL');if(file_exists($target)||!rename($temp,$target))throw new Exception('Cannot install target atomically');$state['installedFiles'][]=$entry['path'];journal();}
  bootstrapModx();
  foreach(array(array('modChunk',$spec['chunk'],'name','snippet','chunk'),array('modTemplate',$spec['template'],'templatename','content','template')) as $definition){list($class,$details,$nameField,$contentField,$kind)=$definition;if($modx->getObject($class,array($nameField=>$details['name'])))throw new Exception('Unexpected existing '.$kind);$object=$modx->newObject($class);$object->fromArray(array($nameField=>$details['name'],'static'=>1,'static_file'=>$details['static_file'],'source'=>0,$contentField=>''));if(!$object->save())throw new Exception('Could not register '.$kind);$state['created'][$kind]=(int)$object->get('id');journal();}
  foreach($bindings as $binding){$object=$modx->newObject('modTemplateVarTemplate');$object->set('tmplvarid',$binding['tmplvarid']);$object->set('templateid',$state['created']['template']);$object->set('rank',$binding['rank']);if(!$object->save())throw new Exception('Could not copy TV binding');}
  preserveCacheAcl();assertHomeUnchanged();$state['phase']='prepared';journal();echo json_encode(array('phase'=>'prepared','home'=>(int)$home['id'],'created'=>$state['created'],'tvBindings'=>count($bindings),'installedFiles'=>count($state['installedFiles']),'homepageSwitched'=>false))."\n";exit;
 }
 if($action==='activate'){
  if(!$state||$state['phase']!=='prepared')throw new Exception('A prepared journal is required');assertBaseline();assertHomeUnchanged();foreach($manifest as $entry)if(hash_file('sha256',$root.'/'.$entry['path'])!==$entry['sha256'])throw new Exception('Installed payload changed');
  bootstrapModx();$home=$modx->getObject('modResource',(int)$state['originalHome']['id']);$state['phase']='activating';journal();$home->set('template',(int)$state['created']['template']);$home->set('editedon',time());if(!$home->save())throw new Exception('Could not activate homepage');
  $current=homeRow();foreach($state['originalHome'] as $key=>$value)if(!in_array($key,array('template','editedon'),true)&&$current[$key]!==$value)throw new Exception('Unexpected homepage field modification: '.$key);
  refreshHomepageCache();$state['phase']='active';$state['activatedAt']=gmdate('c');journal();echo json_encode(array('phase'=>'active','home'=>(int)$current['id'],'template'=>(int)$current['template'],'previousTemplate'=>(int)$state['originalHome']['template'],'php'=>PHP_VERSION,'rollbackAvailable'=>true))."\n";exit;
 }
}catch(Throwable $error){
 $rollback=false;$rollbackError=null;if($state&&isset($state['phase'])&&$state['phase']==='activating'){try{restoreOriginalHome();$rollback=true;}catch(Throwable $secondary){$rollbackError=$secondary->getMessage();}}
 fwrite(STDERR,json_encode(array('action'=>$action,'error'=>$error->getMessage(),'phase'=>$state?$state['phase']:null,'automaticRollback'=>$rollback,'rollbackError'=>$rollbackError),JSON_UNESCAPED_SLASHES)."\n");exit(1);
}
